-- 1409: Follow-up to 1407 — carve the remaining courses whose PRODUCTION
--       description differed from the local snapshot 1407 was generated from.
--
-- 1407 guards each description UPDATE on CHAR_LENGTH(value) = <pre-migration
-- length>. That is what makes it idempotent and safe, but it also means any
-- course edited on prod after the local DB snapshot was taken did not match
-- and was skipped — 24 courses, including C1751 (DP-600), whose prod
-- description was 1900 chars vs 1906 locally.
--
-- These statements were generated by running the same extractor AGAINST THE
-- PRODUCTION DATABASE, so every CHAR_LENGTH guard below is prod's real value.
--
--   course_<SKU>_certification_exam ->  4 new blocks
--   course_<SKU>_funding_and_grant  -> 19 new blocks
--   21 descriptions rewritten
--
-- Partner accreditation is stripped but gets NO block (checkbox-driven via
-- atc_partners) — same decision as 1407.
--
-- 3 of the 24 carry only an inline parenthetical (e.g. C1128's "(Microsoft
-- Learning Partner)" inside a sentence about a partner company). Those are
-- intentionally left alone: removing the phrase would break the sentence.
--
-- Same invariants as 1407: one statement per line for the apply.php splitter,
-- INSERT ... WHERE NOT EXISTS on identifier, CHAR_LENGTH-guarded UPDATEs
-- (idempotent — after the rewrite the row is shorter and matches nothing),
-- SG-only via @mms_instance, verified valid UTF-8.
--
-- Numbered 1409, not 1408: a concurrent session claimed 1408 for
-- 1408-search-redirect-agentic-ai-for-video-creation.sql in the same window.
-- Two files sharing a number make apply.php ordering depend on the rest of the
-- filename, so this one was renumbered rather than left ambiguous.

SET @is_sg := IF(@mms_instance = 'SG', 1, 0);
SET @sd_attr := (SELECT attribute_id FROM eav_attribute WHERE attribute_code = 'short_description' AND entity_type_id = 4);

INSERT INTO `cms_block` (`title`,`identifier`,`content`,`creation_time`,`update_time`,`is_active`) SELECT 'Course C013 — Funding And Grant','course_C013_funding_and_grant','<p>No funding is available for this course</p> <p>For WSQ funding, please checkout the details at&nbsp;<span style="text-decoration: underline;"><a href="https://www.tertiarycourses.com.sg/wsq-project-management-with-generative-ai-genai.html" title="WSQ - Project Management with Generative AI (GenAI)" target="_blank">WSQ - Project Management with Generative AI (GenAI)</a></span><span style="text-decoration: underline;"><a href="https://www.tertiarycourses.com.sg/wsq-comptia-cloud-training.html" title="WSQ - CompTIA Cloud+ Training" target="_blank"><br></a></span></p>',NOW(),NOW(),1 FROM DUAL WHERE @is_sg = 1 AND NOT EXISTS (SELECT 1 FROM `cms_block` WHERE `identifier` = 'course_C013_funding_and_grant');
INSERT IGNORE INTO `cms_block_store` (`block_id`,`store_id`) SELECT `block_id`,0 FROM `cms_block` WHERE `identifier` = 'course_C013_funding_and_grant';
UPDATE `catalog_product_entity_text` SET `value` = '<p>This course, Effective Project Management with Generative AI, is designed to provide professionals with cutting-edge techniques to enhance every phase of project management using AI. You''ll begin by learning how to initiate and plan projects efficiently by developing project charters, engaging stakeholders, and setting comprehensive management plans for scope, cost, schedule, and risks. With GenAI tools, you''ll gain new insights into improving planning effectiveness and achieving superior project outcomes.</p> <p>During the execution and delivery stages, you''ll harness AI to manage teams, resources, and communications, ensuring quality and stakeholder satisfaction. You''ll also explore AI-driven methods to monitor risks, control project changes, and close projects with optimal results. By the end of the course, you''ll be equipped to manage even complex projects more effectively, with advanced skills in AI-based decision-making and real-time risk response.</p>' WHERE `attribute_id` = @sd_attr AND `entity_id` = 13 AND `store_id` = 0 AND CHAR_LENGTH(`value`) = 1666 AND @is_sg = 1;
INSERT INTO `cms_block` (`title`,`identifier`,`content`,`creation_time`,`update_time`,`is_active`) SELECT 'Course C1034 — Funding And Grant','course_C1034_funding_and_grant','<p>No funding is available for this course</p>',NOW(),NOW(),1 FROM DUAL WHERE @is_sg = 1 AND NOT EXISTS (SELECT 1 FROM `cms_block` WHERE `identifier` = 'course_C1034_funding_and_grant');
