UPDATE `catalog_product_entity_text` SET `value` = '<p>Master the art of orchestrating multiple AI agents with AutoGen in this comprehensive course designed for professionals looking to harness the power of collaborative artificial intelligence. Learn how to build intelligent AI agents using AutoGen AgentChat, implement Retrieval-Augmented Generation (RAG) to enhance agent capabilities with real-time data retrieval, and design sophisticated multi-agent workflows that automate complex tasks. This course provides hands-on experience in creating AI systems where multiple agents collaborate, communicate, and solve problems together, giving you a competitive edge in the rapidly evolving AI landscape.</p><p>Gain practical skills in building RAG-powered agents that leverage external knowledge bases for more accurate and contextually relevant responses. Explore how to architect and deploy multi-agent AI workflows using AutoGen, enabling you to automate business processes, streamline decision-making, and build scalable AI solutions. Whether you are a developer, data scientist, or AI enthusiast, this course equips you with the tools and techniques to design, implement, and manage multi-agent AI systems that drive innovation and productivity in your organisation.</p>' WHERE `attribute_id` = @sd_attr AND `entity_id` = 1035 AND `store_id` = 0 AND CHAR_LENGTH(`value`) = 1309 AND @is_sg = 1;
INSERT INTO `cms_block` (`title`,`identifier`,`content`,`creation_time`,`update_time`,`is_active`) SELECT 'Course C1058 — Funding And Grant','course_C1058_funding_and_grant','<p class="p1">No funding is available for this course.</p> <p>For WSQ funding, please checkout the details at&nbsp;<span style="text-decoration: underline;"><a href="https://www.tertiarycourses.com.sg/wsq-mastering-articulate-storyline-360-for-e-learning-content-creation.html" title="WSQ Mastering Articulate Storyline 360 Course">WSQ - Mastering Articulate Storyline 360 for e-Learning Content Creation Course</a></span></p>',NOW(),NOW(),1 FROM DUAL WHERE @is_sg = 1 AND NOT EXISTS (SELECT 1 FROM `cms_block` WHERE `identifier` = 'course_C1058_funding_and_grant');
