UPDATE `catalog_product_entity_text` SET `value` = '<p>Dive into the transformative world of elearning content with our Articulate Storyline 360 Masterclass. This masterclass encapsulates everything, from the very basics of elearning content to the intricate processes of inserting images, characters, external media, and even publishing handouts to Microsoft Word. Be it setting up your project preferences, adjusting slide properties, or exploring the potential of triggers and timings, this training has got you covered.</p> <p>Moreover, with our professionally curated curriculum, you''ll get hands-on experience in creating projects either from existing slides or from scratch. And to ensure that your content is inclusive, we also guide you on accessibility best practices. By the end, not only will you be adept at crafting interactive elearning modules, but you''ll also be proficient in assessing learner engagement through questions and publishing your course online.</p>' WHERE `attribute_id` = @sd_attr AND `entity_id` = 1058 AND `store_id` = 0 AND CHAR_LENGTH(`value`) = 1398 AND @is_sg = 1;
