UPDATE `catalog_product_entity_text` SET `value` = '<p>Elevate your understanding of Robotic Process Automation with our UIPath RPA Essential Training. This meticulously crafted course provides a deep dive into core UIPath operations, offering participants a robust foundation in Control Flow Scripting, and a comprehensive grasp of automating emails, web interactions, and file operations.</p> <p>Beyond the basics, the training delves into sophisticated realms of RPA, including proficient error handling techniques, leveraging the UIPath Orchestrator for centralized robot management, and exploring the potential of cognitive activities. Whether you are a novice or a professional seeking to upgrade your RPA skills, this course provides the expertise you need.</p>' WHERE `attribute_id` = @sd_attr AND `entity_id` = 1150 AND `store_id` = 0 AND CHAR_LENGTH(`value`) = 1148 AND @is_sg = 1;
INSERT INTO `cms_block` (`title`,`identifier`,`content`,`creation_time`,`update_time`,`is_active`) SELECT 'Course C1382 — Funding And Grant','course_C1382_funding_and_grant','<p>For WSQ funding, please checkout the details at <span style="text-decoration: underline;"><a href="https://www.tertiarycourses.com.sg/wsq-create-engaging-content-with-generative-ai-gai.html" title="WSQ">WSQ - Create Engaging Content with Generative AI (GAI)</a></span></p>',NOW(),NOW(),1 FROM DUAL WHERE @is_sg = 1 AND NOT EXISTS (SELECT 1 FROM `cms_block` WHERE `identifier` = 'course_C1382_funding_and_grant');
