UPDATE `catalog_product_entity_text` SET `value` = '<p>Put an AI coworker on your team in this hands-on Claude Cowork Masterclass. Claude Cowork is Anthropic’s agentic AI workspace that works directly with your files and folders — organising documents, drafting reports, building spreadsheets and presentations, and completing multi-step tasks from a single plain-English brief, with no coding required. In this masterclass, you will set up Cowork, connect it to your working folders, and learn to delegate real work to Claude while you stay in control of quality and accuracy.</p> <p>Through practical projects, participants will use Cowork to organise messy folders, produce documents and management reports, process and analyse data, and run research and summarisation tasks end to end. You will learn to brief Claude effectively, run and review multi-step tasks, connect additional tools and integrations, and apply approvals, guardrails and secure practices when working with business data. By the end of the masterclass, you will be able to make Claude Cowork your everyday AI coworker and hand off hours of routine work every week.</p>' WHERE `attribute_id` = @sd_attr AND `entity_id` = 1382 AND `store_id` = 0 AND CHAR_LENGTH(`value`) = 1482 AND @is_sg = 1;
