INSERT INTO `cms_block` (`title`,`identifier`,`content`,`creation_time`,`update_time`,`is_active`) SELECT 'Course C1394 — Funding And Grant','course_C1394_funding_and_grant','<p>No funding is available for this course</p> <p>For WSQ funding, please checkout the details at&nbsp;<span style="text-decoration: underline;"><a href="https://www.tertiarycourses.com.sg/wsq-certified-kubernetes-administrator-cka-exam-prep-synchronous-e-learning.html" title="WSQ - Certified Kubernetes Administrator (CKA) Training (Synchronous e-Learning)">WSQ - Certified Kubernetes Administrator (CKA) Training (Synchronous e-Learning)</a></span><span style="text-decoration: underline;"></span></p>',NOW(),NOW(),1 FROM DUAL WHERE @is_sg = 1 AND NOT EXISTS (SELECT 1 FROM `cms_block` WHERE `identifier` = 'course_C1394_funding_and_grant');
