UPDATE `catalog_product_entity_text` SET `value` = '<p>The DP-600 Microsoft Certified Fabric Analytics Engineer Associate course is designed for data professionals seeking to develop deep expertise in end-to-end analytics using Microsoft Fabric. This course equips learners with practical knowledge on lakehouses, Delta Lake tables, dataflows, real-time intelligence, and Apache Spark integration within the Microsoft Fabric ecosystem. Learners will also explore Fabric’s data warehouse capabilities including data loading, querying, monitoring, and securing analytics environments.</p> <p>Participants will gain hands-on experience working with scalable semantic models in Power BI, performance optimization, and enterprise-grade data governance using Microsoft Purview. The course also covers essential administration tasks and security best practices, ensuring participants are fully prepared to manage and deliver secure, high-performance analytics solutions. Perfect for those preparing for the DP-600 certification, this course empowers data engineers to lead the future of analytics on Microsoft Fabric.</p>' WHERE `attribute_id` = @sd_attr AND `entity_id` = 1751 AND `store_id` = 0 AND CHAR_LENGTH(`value`) = 1900 AND @is_sg = 1;
INSERT INTO `cms_block` (`title`,`identifier`,`content`,`creation_time`,`update_time`,`is_active`) SELECT 'Course C1756 — Funding And Grant','course_C1756_funding_and_grant','<p>No funding is available for this course</p>',NOW(),NOW(),1 FROM DUAL WHERE @is_sg = 1 AND NOT EXISTS (SELECT 1 FROM `cms_block` WHERE `identifier` = 'course_C1756_funding_and_grant');
