UPDATE `catalog_product_entity_text` SET `value` = '<p>The AB-100 Microsoft Certified Agentic AI Business Solutions Architect course equips learners with the knowledge and skills required to design and deliver AI-powered, agentic-first business solutions on the Microsoft platform. Participants will explore planning AI strategies, designing single- and multi-agent solutions with Microsoft 365 Copilot, Copilot Studio and Microsoft Foundry, and grounding agents on trusted business data.</p><p>Learners will gain expertise in designing agent extensibility with Model Context Protocol and Computer Use, orchestrating AI features across Dynamics 365 and Microsoft Power Platform, and deploying solutions with robust testing, application lifecycle management, monitoring and telemetry. Additionally, the course covers securing and governing agents, mitigating prompt manipulation, and applying responsible AI, data residency and compliance controls. By completing this course, participants will be prepared to architect scalable, secure and measurable agentic AI solutions using Microsoft technologies.</p>' WHERE `attribute_id` = @sd_attr AND `entity_id` = 1756 AND `store_id` = 0 AND CHAR_LENGTH(`value`) = 1372 AND @is_sg = 1;
INSERT INTO `cms_block` (`title`,`identifier`,`content`,`creation_time`,`update_time`,`is_active`) SELECT 'Course C1759 — Funding And Grant','course_C1759_funding_and_grant','<p>No funding is available for this course</p>',NOW(),NOW(),1 FROM DUAL WHERE @is_sg = 1 AND NOT EXISTS (SELECT 1 FROM `cms_block` WHERE `identifier` = 'course_C1759_funding_and_grant');
