UPDATE `catalog_product_entity_text` SET `value` = '<p>The AI-200 Microsoft Certified Azure AI Cloud Developer Associate course equips learners with the knowledge and skills required to build, deploy and operate AI cloud solutions on Azure with an emphasis on back-end services and components. Participants will explore developing containerized solutions with Azure Container Registry, Azure Container Apps and Azure Kubernetes Service, and building AI solutions on Azure data management services.</p><p>Learners will gain hands-on expertise working with vector search across Azure Cosmos DB, Azure Database for PostgreSQL and Azure Managed Redis, implementing retrieval-augmented generation, and connecting event- and message-based services with Azure Service Bus, Event Grid and Functions. Additionally, the course covers securing solutions with Azure Key Vault and App Configuration, and monitoring with OpenTelemetry and KQL. By completing this course, participants will be prepared to develop secure, scalable AI cloud applications on Azure.</p>' WHERE `attribute_id` = @sd_attr AND `entity_id` = 1759 AND `store_id` = 0 AND CHAR_LENGTH(`value`) = 1319 AND @is_sg = 1;
INSERT INTO `cms_block` (`title`,`identifier`,`content`,`creation_time`,`update_time`,`is_active`) SELECT 'Course C1760 — Funding And Grant','course_C1760_funding_and_grant','<p>No funding is available for this course</p>',NOW(),NOW(),1 FROM DUAL WHERE @is_sg = 1 AND NOT EXISTS (SELECT 1 FROM `cms_block` WHERE `identifier` = 'course_C1760_funding_and_grant');
