UPDATE `catalog_product_entity_text` SET `value` = '<p>The AB-620 Microsoft Certified AI Agent Builder Associate course equips developers and advanced builders with the knowledge and skills required to design, build, extend and integrate custom AI agents for enterprise-grade solutions in Microsoft Copilot Studio. Participants will explore planning agent solutions, creating agent flows and topics, and configuring advanced responses with custom prompts, knowledge sources and adaptive cards.</p><p>Learners will gain hands-on expertise integrating agents with enterprise knowledge sources, Model Context Protocol (MCP) tools, custom connectors and REST APIs, building multi-agent solutions with the Agent2Agent (A2A) protocol and Microsoft Foundry, and connecting to Azure AI Search and Microsoft Fabric. Additionally, the course covers testing and evaluating agents and applying application lifecycle management with Microsoft Power Platform Pipelines. By completing this course, participants will be prepared to build and ship integrated, production-ready AI agents in Copilot Studio.</p>' WHERE `attribute_id` = @sd_attr AND `entity_id` = 1760 AND `store_id` = 0 AND CHAR_LENGTH(`value`) = 1361 AND @is_sg = 1;
INSERT INTO `cms_block` (`title`,`identifier`,`content`,`creation_time`,`update_time`,`is_active`) SELECT 'Course C430 — Funding And Grant','course_C430_funding_and_grant','<p>No funding is available for this course.</p>',NOW(),NOW(),1 FROM DUAL WHERE @is_sg = 1 AND NOT EXISTS (SELECT 1 FROM `cms_block` WHERE `identifier` = 'course_C430_funding_and_grant');
