UPDATE `catalog_product_entity_text` SET `value` = '<p>Master the full power of Tableau with the Tableau Desktop Masterclass. This hands-on masterclass takes you from Tableau fundamentals to advanced analytics — explore the Tableau interface, work with dimensions and measures, connect to diverse data sources, and build compelling views with data joins, blending and aggregations.</p> <p>Go beyond the basics with data transformation, interactive dashboards and stories, calculated fields and parameters, and advanced analytics including trend lines, forecasting, clustering and Level of Detail (LOD) expressions. Round off with map analytics using map services and Mapbox integration. With hands-on exercises and expert-led content, you will leave able to turn raw data into compelling visual narratives with Tableau Desktop.</p>' WHERE `attribute_id` = @sd_attr AND `entity_id` = 469 AND `store_id` = 0 AND CHAR_LENGTH(`value`) = 1221 AND @is_sg = 1;
INSERT INTO `cms_block` (`title`,`identifier`,`content`,`creation_time`,`update_time`,`is_active`) SELECT 'Course C691 — Funding And Grant','course_C691_funding_and_grant','<p>No funding is available for this course.</p><p>For WSQ funding, please checkout the details at <u><a href="https://www.tertiarycourses.com.sg/wsq-dialogflow-ai-chatbot-course.html" rel="noopener noreferrer" target="_blank">WSQ - Dialogflow AI Chatbot Platform Management for Beginners</a></u></p>',NOW(),NOW(),1 FROM DUAL WHERE @is_sg = 1 AND NOT EXISTS (SELECT 1 FROM `cms_block` WHERE `identifier` = 'course_C691_funding_and_grant');
