UPDATE `catalog_product_entity_text` SET `value` = '<p>This course introduces participants to the practical development and deployment of a digital AI agent workforce using the OpenClaw platform. Participants will learn how to install, configure, and operate OpenClaw to build autonomous agents that can perform tasks, automate workflows, and support digital operations across organizations.</p><p>The course begins with the setup and configuration of the OpenClaw platform, including the installation of required components, integration of language models, and deployment of a working AI agent environment. Participants will gain a clear understanding of the OpenClaw architecture and how agents operate within the system.</p><p>Participants will then learn how to design and develop OpenClaw agent skills, create task workflows, and build specialized sub-agents that collaborate to perform complex tasks. The course also covers memory management techniques to improve agent performance and ensure efficient task execution.</p><p>Finally, participants will explore how to optimize and secure an OpenClaw digital workforce, including implementing security best practices, managing agent permissions, improving context and memory efficiency, and applying token cost optimization strategies to ensure scalable and sustainable AI agent deployment.</p><p>By the end of the course, participants will be able to deploy, manage, and optimize OpenClaw agents and sub-agents to support real-world automation and digital workforce transformation initiatives</p>' WHERE `attribute_id` = @sd_attr AND `entity_id` = 691 AND `store_id` = 0 AND CHAR_LENGTH(`value`) = 1837 AND @is_sg = 1;
INSERT INTO `cms_block` (`title`,`identifier`,`content`,`creation_time`,`update_time`,`is_active`) SELECT 'Course C711 — Funding And Grant','course_C711_funding_and_grant','<p>No funding is available for this course</p>',NOW(),NOW(),1 FROM DUAL WHERE @is_sg = 1 AND NOT EXISTS (SELECT 1 FROM `cms_block` WHERE `identifier` = 'course_C711_funding_and_grant');
