UPDATE `catalog_product_entity_text` SET `value` = '<p>The AB-731 Microsoft Certified AI Transformation Leader course equips business leaders and decision-makers with the knowledge and skills required to recognize AI opportunities, plan AI adoption, and drive innovation with Microsoft 365 Copilot and Microsoft Foundry Tools — no coding required. Participants will explore the business value of generative AI, prompt engineering, grounding and retrieval-augmented generation, and how to align AI investments with business goals.</p><p>Learners will gain expertise in mapping business processes to Microsoft 365 Copilot, Copilot Studio, Microsoft Graph and Foundry Tools, championing responsible AI, and building an organization-wide adoption strategy with governance, an AI council and a champions program. Additionally, the course covers Copilot licensing and Foundry subscription models, AI security and cost considerations. By completing this course, participants will be prepared to lead AI transformation and adoption across their teams and organization.</p>' WHERE `attribute_id` = @sd_attr AND `entity_id` = 711 AND `store_id` = 0 AND CHAR_LENGTH(`value`) = 1333 AND @is_sg = 1;
INSERT INTO `cms_block` (`title`,`identifier`,`content`,`creation_time`,`update_time`,`is_active`) SELECT 'Course C765 — Funding And Grant','course_C765_funding_and_grant','<p>No funding is available for this course</p><p>For WSQ funding, please checkout the details at <u><a href="https://www.tertiarycourses.com.sg/wsq-develop-generative-ai-solutions-with-azure-openai-service.html" rel="noopener noreferrer" target="_blank">WSQ - Develop Generative AI Solutions with Azure OpenAI Service</a></u></p>',NOW(),NOW(),1 FROM DUAL WHERE @is_sg = 1 AND NOT EXISTS (SELECT 1 FROM `cms_block` WHERE `identifier` = 'course_C765_funding_and_grant');
INSERT IGNORE INTO `cms_block_store` (`block_id`,`store_id`) SELECT `block_id`,0 FROM `cms_block` WHERE `identifier` = 'course_C765_funding_and_grant';
UPDATE `catalog_product_entity_text` SET `value` = '<p>Gain the skills to design, build, and deploy sophisticated multi-agent AI systems using the OpenAI Agent Development Kit. This hands-on course takes you from foundational AI agent concepts through advanced orchestration techniques, equipping you with the expertise to create intelligent agents that collaborate, reason, and solve complex tasks autonomously. You will learn to build RAG agents powered by word embeddings and vector databases, orchestrate multiple agents using sequential and parallel workflows, and implement handoff and routing strategies for seamless agent collaboration.</p><p>Take your AI capabilities further by mastering the Model Context Protocol (MCP) for creating custom tools and leveraging agents as tools within larger systems. The course culminates with practical training on fine-tuning large language models, giving you the ability to customize AI behaviour for domain-specific applications. Whether you are an AI developer, solutions architect, or technology leader, this course delivers the practical knowledge you need to harness the full potential of multi-agent AI systems and drive innovation within your organisation.</p>' WHERE `attribute_id` = @sd_attr AND `entity_id` = 765 AND `store_id` = 0 AND CHAR_LENGTH(`value`) = 1530 AND @is_sg = 1;
INSERT INTO `cms_block` (`title`,`identifier`,`content`,`creation_time`,`update_time`,`is_active`) SELECT 'Course C814 — Funding And Grant','course_C814_funding_and_grant','<p>No funding is available for this course.</p><p>For WSQ funding, please checkout the details at <u><a href="https://www.tertiarycourses.com.sg/wsq-develop-chatbot-content-strategy-with-microsoft-copilot-studio.html" rel="noopener noreferrer" target="_blank">Develop Intelligent Chatbots with Microsoft Copilot Studio and Generative AI</a></u></p>',NOW(),NOW(),1 FROM DUAL WHERE @is_sg = 1 AND NOT EXISTS (SELECT 1 FROM `cms_block` WHERE `identifier` = 'course_C814_funding_and_grant');
INSERT IGNORE INTO `cms_block_store` (`block_id`,`store_id`) SELECT `block_id`,0 FROM `cms_block` WHERE `identifier` = 'course_C814_funding_and_grant';
UPDATE `catalog_product_entity_text` SET `value` = '<p>Dive into the world of intelligent chatbot creation with our comprehensive course on Microsoft Copilot Studio. This course offers a deep dive into the cutting-edge technology of AI chatbots, focusing on using Microsoft Copilot Studio for developing sophisticated, responsive chatbot applications. You''ll learn the intricacies of natural language processing, machine learning algorithms, and how to integrate these chatbots into various digital platforms to enhance user experience and engagement.</p><p>Our hands-on approach will guide you through the process of designing, building, and deploying chatbots that can understand and interpret human language, make decisions, and provide valuable interactions. The course also covers best practices for optimizing chatbot performance, ensuring security and privacy, and measuring the effectiveness of your chatbot strategies. By the end of the course, you will have the necessary skills to create intelligent chatbots that can revolutionize customer service, e-commerce, and digital marketing efforts.</p>' WHERE `attribute_id` = @sd_attr AND `entity_id` = 814 AND `store_id` = 0 AND CHAR_LENGTH(`value`) = 1442 AND @is_sg = 1;
INSERT INTO `cms_block` (`title`,`identifier`,`content`,`creation_time`,`update_time`,`is_active`) SELECT 'Course C864 — Funding And Grant','course_C864_funding_and_grant','<p>No funding is available for this course</p>',NOW(),NOW(),1 FROM DUAL WHERE @is_sg = 1 AND NOT EXISTS (SELECT 1 FROM `cms_block` WHERE `identifier` = 'course_C864_funding_and_grant');
INSERT IGNORE INTO `cms_block_store` (`block_id`,`store_id`) SELECT `block_id`,0 FROM `cms_block` WHERE `identifier` = 'course_C864_funding_and_grant';
UPDATE `catalog_product_entity_text` SET `value` = '<p>The AB-730 Microsoft Certified AI Business Professional course equips business users and professionals with the knowledge and skills required to use generative AI productivity tools such as Microsoft 365 Copilot and agents like Researcher and Analyst to improve daily work and make better decisions — without building AI apps or writing code. Participants will explore generative AI fundamentals, how Copilot keeps information private and secure, and how to apply responsible AI and data protection practices.</p><p>Learners will gain expertise in creating effective prompts, saving, scheduling and sharing prompts, managing conversations, and building and configuring Microsoft 365 Copilot agents. Additionally, the course covers drafting business documents, generating management summaries, moving insights between Microsoft 365 apps, and using Copilot for meetings and collaboration with Copilot Pages. By completing this course, participants will be prepared to work more productively and confidently with AI in everyday business contexts.</p>' WHERE `attribute_id` = @sd_attr AND `entity_id` = 864 AND `store_id` = 0 AND CHAR_LENGTH(`value`) = 1371 AND @is_sg = 1;
INSERT INTO `cms_block` (`title`,`identifier`,`content`,`creation_time`,`update_time`,`is_active`) SELECT 'Course C926 — Funding And Grant','course_C926_funding_and_grant','<p>No funding is available for this course</p>',NOW(),NOW(),1 FROM DUAL WHERE @is_sg = 1 AND NOT EXISTS (SELECT 1 FROM `cms_block` WHERE `identifier` = 'course_C926_funding_and_grant');
INSERT IGNORE INTO `cms_block_store` (`block_id`,`store_id`) SELECT `block_id`,0 FROM `cms_block` WHERE `identifier` = 'course_C926_funding_and_grant';
UPDATE `catalog_product_entity_text` SET `value` = '<p>The AI-103 Microsoft Certified Azure AI Apps and Agents Developer Associate course equips learners with the knowledge and skills required to build, manage and deploy AI apps and agents on Azure using Microsoft Foundry. Participants will explore planning and managing Azure AI solutions, choosing the right models and Foundry services, and implementing generative AI and agentic solutions with retrieval-augmented generation, multi-agent orchestration and responsible AI.</p><p>Learners will gain hands-on expertise implementing computer vision, text analysis and information extraction solutions — from image and video generation and multimodal understanding to sentiment analysis, speech, translation, and OCR-based document extraction with Azure Content Understanding. Additionally, the course covers securing, monitoring and operationalizing AI systems with observability, guardrails and CI/CD. By completing this course, participants will be prepared to develop and operate production-grade AI apps and agents on Azure.</p>' WHERE `attribute_id` = @sd_attr AND `entity_id` = 926 AND `store_id` = 0 AND CHAR_LENGTH(`value`) = 1350 AND @is_sg = 1;
INSERT INTO `cms_block` (`title`,`identifier`,`content`,`creation_time`,`update_time`,`is_active`) SELECT 'Course C991 — Funding And Grant','course_C991_funding_and_grant','<p>No funding is available for this course</p><p>For WSQ funding, please checkout the details at <u><a href="https://www.tertiarycourses.com.sg/wsq-building-multi-agent-ai-systems.html" rel="noopener noreferrer" target="_blank">WSQ - Building Multi-Agent AI Systems</a></u></p>',NOW(),NOW(),1 FROM DUAL WHERE @is_sg = 1 AND NOT EXISTS (SELECT 1 FROM `cms_block` WHERE `identifier` = 'course_C991_funding_and_grant');
INSERT IGNORE INTO `cms_block_store` (`block_id`,`store_id`) SELECT `block_id`,0 FROM `cms_block` WHERE `identifier` = 'course_C991_funding_and_grant';
UPDATE `catalog_product_entity_text` SET `value` = '<p>Dive into the world of Agentic Process Automation by mastering the orchestration of Large Language Models (LLMs) and building advanced AI-driven applications. This course covers the essentials of LLM AI orchestration, from running local LLMs to building and debugging LLM apps, and offers a deep dive into Retrieval-Augmented Generation (RAG) with techniques like text embedding, vector databases, and similarity searches. You''ll also learn to create robust RAG systems that enhance AI capabilities.</p><p>Further, explore multi-agent AI workflows by implementing the ReAct agent framework, equipping agents with tools and skills, and setting up multi-agent systems using leading platforms like LangGraph, CrewAI, and AutoGen. Ideal for professionals looking to innovate with AI technologies and build complex automation systems.</p>' WHERE `attribute_id` = @sd_attr AND `entity_id` = 991 AND `store_id` = 0 AND CHAR_LENGTH(`value`) = 1152 AND @is_sg = 1;
INSERT INTO `cms_block` (`title`,`identifier`,`content`,`creation_time`,`update_time`,`is_active`) SELECT 'Course TGS-2023037854 — Certification Exam','course_TGS-2023037854_certification_exam','<p>Once you are prepared for the exam, you can register for the certification&nbsp;<span style="text-decoration: underline;"><a href="https://home.pearsonvue.com/cisco.aspx" title="Cisco Certification" target="_blank">here</a></span>. We are Authorised Pearson Vue Testing Center. You can take the certification exam at our test center. Note that the course fee does not include the certification exam fee.</p>',NOW(),NOW(),1 FROM DUAL WHERE @is_sg = 1 AND NOT EXISTS (SELECT 1 FROM `cms_block` WHERE `identifier` = 'course_TGS-2023037854_certification_exam');
INSERT IGNORE INTO `cms_block_store` (`block_id`,`store_id`) SELECT `block_id`,0 FROM `cms_block` WHERE `identifier` = 'course_TGS-2023037854_certification_exam';
UPDATE `catalog_product_entity_text` SET `value` = '<p>The Cisco Certified Network Associate (CCNA) course offers an in-depth dive into the world of networking, providing participants with the knowledge and skills needed to design, configure, and manage both wired and wireless network connections. Whether you''re new to the field or looking to enhance your professional portfolio, this course ensures a solid grounding in core networking concepts, aligning with industry best practices and standards.</p> <p>Beyond just theoretical understanding, our CCNA training emphasizes hands-on experience and real-world application. Participants will tackle a range of networking challenges, from IP addressing and routing to network security and automation, all under the guidance of experienced instructors with deep industry insights. By the end of the course, you''ll be well-prepared to ace the CCNA certification exam and set a strong foundation for a thriving career in networking.</p>' WHERE `attribute_id` = @sd_attr AND `entity_id` = 1450 AND `store_id` = 0 AND CHAR_LENGTH(`value`) = 1388 AND @is_sg = 1;
INSERT INTO `cms_block` (`title`,`identifier`,`content`,`creation_time`,`update_time`,`is_active`) SELECT 'Course TGS-2023040472 — Certification Exam','course_TGS-2023040472_certification_exam','<p>We are <strong>Authorised Pearson Vue Testing Center</strong>. Once you have prepared for the exam, you can register for the certification<u> <a href="https://learn.microsoft.com/en-us/credentials/certifications/power-automate-rpa-developer-associate/?practice-assessment-type=certification" rel="noopener noreferrer" target="_blank">here</a></u>. The course fee does not include the certification exam fee.</p><p>You can purchase the exam voucher (one of the lowest prices in Singapore) at<u> <a href="https://www.tertiarycourses.com.sg/microsoft-role-based-certification-exam-vouchers.html" rel="noopener noreferrer" target="_blank">Microsoft Role-Based Certification Exam Voucher</a></u>.</p>',NOW(),NOW(),1 FROM DUAL WHERE @is_sg = 1 AND NOT EXISTS (SELECT 1 FROM `cms_block` WHERE `identifier` = 'course_TGS-2023040472_certification_exam');
INSERT IGNORE INTO `cms_block_store` (`block_id`,`store_id`) SELECT `block_id`,0 FROM `cms_block` WHERE `identifier` = 'course_TGS-2023040472_certification_exam';
UPDATE `catalog_product_entity_text` SET `value` = '<p>WSQ Hands On Power Automate Desktop RPA for Work Process Automation equips learners with practical skills to identify automation opportunities across devices, applications, and databases. Through hands-on training, participants will gain experience in using Power Automate Desktop to design, test, and implement robotic process automation workflows. Learners will understand how to evaluate feasibility, troubleshoot integration issues, and optimize automation using real-time data and APIs.</p><p>The course covers core topics including automation fundamentals, integrating advanced logic, leveraging different technologies within Power Automate, and building secure custom connectors. By the end of the course, learners will be equipped to enhance digital transformation in their workplace by automating repetitive tasks, increasing efficiency, and resolving technical compatibility issues in automation systems.</p>' WHERE `attribute_id` = @sd_attr AND `entity_id` = 1229 AND `store_id` = 0 AND CHAR_LENGTH(`value`) = 1897 AND @is_sg = 1;
